entries[12830] = { ["name"] = "Plans: Corruption", ["text"] = "Requires Blacksmithing (290)\nRequiresMaster Swordsmith\nUse: Teaches you how to make Corruption.\nCorruption\nBinds when picked up\nTwo-Hand Sword\n119 - 179 Damage Speed 3.00\n(49.67 damage per second)\n+30 Strength\n+30 Stamina\n-40 Spirit\nDurability 100 / 100\nRequires Level 53\nRequires Thorium Bar (40), Arcanite Bar (2), Demonic Rune (16), Essence of Undeath (8), Blue Sapphire (2), Dense Grinding Stone (2), Rugged Leather (4)" }
entries[12831] = { ["name"] = "Plans: Blood Talon", ["text"] = "Requires Blacksmithing (300)\nRequiresWeaponsmith\nUse: Teaches you how to make Blood Talon.\nBlood Talon\nBinds when picked up\nMain Hand Fist Weapon\n35 - 67 Damage Speed 1.30\n(39.23 damage per second)\nDurability 65 / 65\nRequires Level 55\nChance on hit: Wounds the target causing them to bleed for 100 damage over 30 sec.\nRequires Enchanted Thorium Bar (10), Arcanite Bar (10), Demonic Rune (8), Star Ruby (10), Dense Grinding Stone (2)" }
entries[12832] = { ["name"] = "Plans: Darkspear", ["text"] = "Requires Blacksmithing (300)\nRequiresWeaponsmith\nUse: Teaches you how to make a Darkspear.\nDarkspear\nBinds when equipped\nTwo-Hand Polearm\n131 - 197 Damage Speed 3.20\n(51.25 damage per second)\nDurability 100 / 100\nRequires Level 55\nChance on hit: Party members have chance to crit increased by 4%. Lasts for 20 sec.\nRequires Enchanted Thorium Bar (20), Powerful Mojo (20), Huge Emerald (2), Azerothian Diamond (2), Dense Grinding Stone (2)" }
entries[12833] = { ["name"] = "Plans: Hammer of the Titans", ["text"] = "Requires Blacksmithing (300)\nRequiresMaster Hammersmith\nUse: Teaches you how to make a Hammer of the Titans.\nHammer of the Titans\nBinds when equipped\nTwo-Hand Mace\n163 - 246 Damage Speed 3.80\n(53.82 damage per second)\n+15 Strength\nDurability 100 / 100\nRequires Level 58\nChance on hit: Stuns target for 3 sec.\nRequires Thorium Bar (50), Arcanite Bar (15), Guardian Stone (4), Enchanted Leather (6), Essence of Earth (10)" }
entries[12834] = { ["name"] = "Plans: Arcanite Champion", ["text"] = "Requires Blacksmithing (300)\nRequiresMaster Swordsmith\nUse: Teaches you how to make an Arcanite Champion.\nArcanite Champion\nBinds when equipped\nTwo-Hand Sword\n129 - 194 Damage Speed 3.00\n(53.83 damage per second)\nDurability 100 / 100\nRequires Level 58\nChance on hit: Heal self for 270 to 450 and Increases Strength by 120 for 30 sec.\nRequires Arcanite Bar (15), Azerothian Diamond (8), Righteous Orb , Large Opal (4), Enchanted Leather (8), Dense Grinding Stone (2)" }
entries[12835] = { ["name"] = "Plans: Annihilator", ["text"] = "Requires Blacksmithing (300)\nRequiresMaster Axesmith\nUse: Teaches you how to make an Annihilator.\nAnnihilator\nBinds when equipped\nMain Hand Axe\n49 - 92 Damage Speed 1.70\n(41.47 damage per second)\nDurability 90 / 90\nRequires Level 58\nChance on hit: Reduces an enemy's armor by 200. Stacks up to 3 times.\nRequires Thorium Bar (40), Arcanite Bar (12), Essence of Undeath (10), Huge Emerald (8), Dense Grinding Stone (2), Enchanted Leather (4)" }
entries[12836] = { ["name"] = "Plans: Frostguard", ["text"] = "Requires Blacksmithing (300)\nRequiresMaster Swordsmith\nUse: Teaches you how to make a Frostguard.\nFrostguard\nBinds when equipped\nMain Hand Sword\n66 - 124 Damage Speed 2.30\n(41.30 damage per second)\nDurability 90 / 90\nRequires Level 58\nChance on hit: Target's movement slowed by 30% and increasing the time between attacks by 25% for 5 sec.\nRequires Arcanite Bar (18), Blue Sapphire (8), Azerothian Diamond (8), Essence of Water (4), Dense Grinding Stone (2), Enchanted Leather (4)" }
entries[12837] = { ["name"] = "Plans: Masterwork Stormhammer", ["text"] = "Requires Blacksmithing (300)\nRequiresMaster Hammersmith\nUse: Teaches you how to make a Masterwork Stormhammer.\nMasterwork Stormhammer\nBinds when equipped\nMain Hand Mace\n58 - 108 Damage Speed 2.00\n(41.50 damage per second)\nDurability 90 / 90\nRequires Level 57\nChance on hit: Blasts up to 3 targets for 105 to 145 Nature damage.\nRequires Enchanted Thorium Bar (20), Huge Emerald (8), Large Opal (8), Essence of Earth (6), Enchanted Leather (4)" }
